using BetaFit.Desktop.Services;
namespace BetaFit.Desktop.Controls;
public sealed class UcSettings:UserControl { public UcSettings(IBetaFitApiService api,Session session){Dock=DockStyle.Fill;BackColor=Color.FromArgb(15,18,23);Padding=new Padding(28);var title=new Label{Text="Configurações",ForeColor=Color.White,Font=new Font("Segoe UI Semibold",22),Dock=DockStyle.Top,Height=50};var info=new Label{Text=$"Usuário: {session.UserName}\nPerfil: {session.Role}\n\nA URL da API é definida em appsettings.json ou BETAFIT_BetaFitApi__BaseUrl.",ForeColor=Color.Gainsboro,Font=new Font("Segoe UI",11),AutoSize=true,Dock=DockStyle.Top,Padding=new Padding(0,20,0,0)};Controls.Add(info);Controls.Add(title);} }